import{_ as s,l,o as i,c as o,v as e,p as n,x as r,d as p,i as g,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Chaitin–Briggs","description":"","frontmatter":{"title":"Chaitin–Briggs","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chaitin-briggs.md","filePath":"cs/chaitin-briggs.md","lastUpdated":1789023840000}'),d={name:"cs/chaitin-briggs.md"};function c(B,a,_,A,m,E){const t=l("Mermaid");return i(),o("div",null,[a[1]||(a[1]=e('<h1 id="chaitin–briggs" tabindex="-1">Chaitin–Briggs <a class="header-anchor" href="#chaitin–briggs" aria-label="Permalink to &quot;Chaitin–Briggs&quot;">​</a></h1><div class="epigraph"><p>冲突图上简化低度数节点，溢出时乐观着色：Briggs 允许度数 ≥K 的点仍试着着色，减少不必要 spill。</p><footer>—— 据 Chaitin et al., 1981；Briggs, Cooper and Torczon, Improvements to Graph Coloring Register Allocation, 1994；龙书整理</footer></div><p>上一课<a href="/cs/linear-scan-regalloc">线性扫描</a>用区间。主干着色课已给冲突图。缺口是 <strong>Chaitin–Briggs 启发式</strong>：简化、合并、溢出选择、乐观着色。本课钉迭代，不写合并细节——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>K 着色 NP。Chaitin：反复去掉 \\(deg\\lt K\\) 的点压栈，剩下高度数当溢出候选，插入 spill 后重建图。Briggs：压栈时对 \\(deg\\ge K\\) 也压，弹出时再试着色，成功则免一次 spill。缺口是<strong>这套栈机</strong>，不是线性扫描的区间表。</p><p>SSA 冲突图是弦图，可多项式着色——点名；析构后一般不是。</p><h3 id="乐观不是「忽略冲突」" tabindex="-1">乐观不是「忽略冲突」 <a class="header-anchor" href="#乐观不是「忽略冲突」" aria-label="Permalink to &quot;乐观不是「忽略冲突」&quot;">​</a></h3><p>弹出时仍检查邻居颜色；失败才真溢出。不是随便同色。</p><p><span class="marginnote">Chaitin 1981/82。Briggs 1994 TOPLAS。George–Appel 迭代合并。本课 Briggs 乐观为核心增量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建图。可选保守合并。简化循环。选溢出代价（循环深度、use 密度）。重写 spill，迭代直到可着色。弹出着色。</p>',11)),(i(),n(h,null,{default:r(()=>[g(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IG%5B%22%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%20--%3E%20SIM%5B%22%E7%AE%80%E5%8C%96%20%2F%20%E4%B9%90%E8%A7%82%E5%8E%8B%E6%A0%88%22%5D%0A%20%20SIM%20--%3E%20SP%5B%22%E6%BA%A2%E5%87%BA%E9%87%8D%E5%86%99%22%5D%0A%20%20SP%20--%3E%20IG%0A%20%20SIM%20--%3E%20COL%5B%22%E5%BC%B9%E5%87%BA%E7%9D%80%E8%89%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与调用约定：预着色节点（物理寄存器约束）固定颜色，图更大。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>凝聚：无限迭代要防。代价模型错会溢出热区间。不要在 JIT 热路径上跑多次全图重建——这是 AOT 更常见。</p><p>与线性扫描：同一函数可比较 spill 数，作为编译器质量指标。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 George–Appel。后课默认：AOT 可用 Briggs 着色。下一课合并与拆分：对付拷贝与长区间。</p><p>也不把图着色当地图四色课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Chaitin 简化+溢出；Briggs 乐观少 spill。</li><li>预着色尊重 ABI。</li><li>SSA 上弦图是特例。</li><li>出处：Chaitin et al.；Briggs, Cooper and Torczon, 1994；龙书。</li></ul>',9))])}const f=s(d,[["render",c]]);export{C as __pageData,f as default};
